package college.ems.servlet;
import college.ems.dao.EntrepreneurDAO;import college.ems.model.Entrepreneur;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.time.LocalDate;import java.util.regex.Pattern;
@WebServlet("/entrepreneurs/*") public class EntrepreneurServlet extends HttpServlet{
 private final EntrepreneurDAO dao=new EntrepreneurDAO();
 @Override protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String action=path(req);try{if("/new".equals(action)||"/edit".equals(action)){int id=parseId(req.getParameter("id"));req.setAttribute("record",id==0?new Entrepreneur():dao.findById(id));if(id>0&&req.getAttribute("record")==null){resp.sendError(404);return;}req.getRequestDispatcher("/WEB-INF/views/entrepreneur-form.jsp").forward(req,resp);return;}req.setAttribute("records",dao.findAll(req.getParameter("q"),req.getParameter("status")));req.getRequestDispatcher("/WEB-INF/views/entrepreneurs.jsp").forward(req,resp);}catch(Exception ex){getServletContext().log("Entrepreneur page failed",ex);req.setAttribute("error","Could not load entrepreneur records. Check the database configuration.");req.setAttribute("records",java.util.List.of());req.getRequestDispatcher("/WEB-INF/views/entrepreneurs.jsp").forward(req,resp);}}
 @Override protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{req.setCharacterEncoding("UTF-8");String action=path(req);try{if("/delete".equals(action)){dao.delete(parseId(req.getParameter("id")));flash(req,"Entrepreneur deleted.");resp.sendRedirect(req.getContextPath()+"/entrepreneurs");return;}Entrepreneur e=fromRequest(req);validate(e);boolean editing=e.getEntrepreneurId()>0;if(editing)dao.update(e);else dao.insert(e);flash(req,editing?"Entrepreneur updated.":"Entrepreneur added.");resp.sendRedirect(req.getContextPath()+"/entrepreneurs");}catch(IllegalArgumentException ex){req.setAttribute("error",ex.getMessage());req.setAttribute("record",fromRequest(req));req.getRequestDispatcher("/WEB-INF/views/entrepreneur-form.jsp").forward(req,resp);}catch(Exception ex){getServletContext().log("Entrepreneur save failed",ex);req.setAttribute("error",ex instanceof java.sql.SQLIntegrityConstraintViolationException?"That email address is already registered.":"Could not save the record. Check the fields and database connection.");req.setAttribute("record",fromRequest(req));req.getRequestDispatcher("/WEB-INF/views/entrepreneur-form.jsp").forward(req,resp);}}
 private Entrepreneur fromRequest(HttpServletRequest q){Entrepreneur e=new Entrepreneur();try{if(q.getParameter("id")!=null&&!q.getParameter("id").isBlank())e.setEntrepreneurId(parseId(q.getParameter("id")));e.setFullName(value(q,"fullName"));e.setEmail(value(q,"email"));e.setPhone(value(q,"phone"));e.setGender(value(q,"gender"));e.setAddress(value(q,"address"));e.setCity(value(q,"city"));e.setState(value(q,"state"));e.setStatus(value(q,"status"));if(!value(q,"registrationDate").isBlank())e.setRegistrationDate(LocalDate.parse(value(q,"registrationDate")));if(!value(q,"dateOfBirth").isBlank())e.setDateOfBirth(LocalDate.parse(value(q,"dateOfBirth")));}catch(Exception ignored){}return e;}
 private void validate(Entrepreneur e){if(e.getFullName()==null||e.getFullName().isBlank()||e.getEmail()==null||e.getEmail().isBlank()||e.getRegistrationDate()==null)throw new IllegalArgumentException("Full name, email and registration date are required.");if(!Pattern.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$",e.getEmail()))throw new IllegalArgumentException("Enter a valid email address.");if(!"Active".equals(e.getStatus())&&!"Pending".equals(e.getStatus())&&!"Inactive".equals(e.getStatus()))throw new IllegalArgumentException("Choose a valid status.");}
 private static String value(HttpServletRequest r,String key){return r.getParameter(key)==null?"":r.getParameter(key).trim();}private static int parseId(String s){try{int id=Integer.parseInt(s);if(id<1)throw new NumberFormatException();return id;}catch(Exception e){if(s==null||s.isBlank())return 0;throw new IllegalArgumentException("Invalid record number.");}}private static String path(HttpServletRequest r){return r.getPathInfo()==null?"/":r.getPathInfo();}private static void flash(HttpServletRequest r,String msg){r.getSession().setAttribute("notice",msg);}
}
